class ThreadPool {
  private queue: Task[] = [];
  private workers: Worker[];

  constructor(size: number) {
    // Created exactly once, at startup
    this.workers = Array.from({ length: size }, () => this.spawnWorker());
  }

  submit(task: Task) {
    this.queue.push(task); // never spawns a new thread
  }

  private spawnWorker(): Worker {
    return runLoop(async () => {
      while (true) {
        const task = this.queue.shift();
        if (task) await task.run();
        else await yieldToScheduler();
      }
    });
  }
}

const pool = new ThreadPool(20);
server.on("request", (req, res) => {
  pool.submit({ run: () => handleRequest(req, res) });
});
